export const siteMetadata = {
  productName: 'NCR Reorder Control Pack',
  siteUrl: 'https://samuelfrench.github.io/form-reorder-passive-site/',
  description:
    'Static workbook, printable PDFs, CSV templates, proof checklist, vendor quote form, and pad/carton labels for sequentially numbered NCR and carbonless form reorders.',
  previewImagePath: './ncr-reorder-control-pack-preview.svg',
  previewImageUrl: 'https://samuelfrench.github.io/form-reorder-passive-site/ncr-reorder-control-pack-preview.png',
  price: '99.00',
  currency: 'USD',
};

export function buildProductJsonLd(checkoutUrl?: string): string {
  const url = checkoutUrl?.trim() || siteMetadata.siteUrl;
  const product = {
    '@context': 'https://schema.org',
    '@type': 'Product',
    name: siteMetadata.productName,
    description: siteMetadata.description,
    image: siteMetadata.previewImageUrl,
    brand: {
      '@type': 'Brand',
      name: siteMetadata.productName,
    },
    offers: {
      '@type': 'Offer',
      price: siteMetadata.price,
      priceCurrency: siteMetadata.currency,
      url,
      availability: 'https://schema.org/InStock',
    },
  };

  return JSON.stringify(product);
}
